/**
 * Unit tests for MathUtils.lcm
 */
public class MathUtils_lcm_TriageGen1Test {







    @Test
    public void testLcmPositiveNumbers() {
        // Standard case: lcm(4, 6) = 12
        assertEquals(12, MathUtils.lcm(4, 6));
        // Standard case: lcm(3, 5) = 15
        assertEquals(15, MathUtils.lcm(3, 5));
        // Standard case: lcm(7, 7) = 7
