package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.lcm
 */
public class MathUtils_lcm_TriageGen1Test {









    @Test
    public void testLcmWithNegativeNumbers() {
        // The implementation uses Math.abs on the result
        // lcm(-4, 6) -> gcd(-4, 6) is likely 2 or -2 depending on gcd implementation
        // Based on code: Math.abs(mulAndCheck(a / gcd(a, b), b))
        assertEquals(12, MathUtils.lcm(-4, 6));
        assertEquals(12, MathUtils.lcm(4, -6));
        assertEquals(12, MathUtils.lcm(-4, -6));
    }


}

